```js
      {% if ai_suggestions_enabled %}
      const suggestButton = document.getElementById('suggest-button');
      const suggestionPanel = document.querySelector('.ai-suggestions');
      const suggestedTagsContainer = document.querySelector('.ai-suggested-tags');
      const suggestedDescriptionContainer = document.querySelector('.ai-suggested-description');
      const suggestionRowTemplate = document.getElementById('ai-suggestion-template');

      function updateSuggestionPanelVisibility() {
        const hasSuggestions = suggestionPanel.querySelector('.ai-suggestion-row');
        suggestionPanel.style['display'] = hasSuggestions ? 'block' : 'none';
      }

      function addSuggestion(container, text, keep) {
        const row = suggestionRowTemplate.content.firstElementChild.cloneNode(true);
        row.querySelector('.ai-suggestion-text').textContent = text;
        row.querySelector('.ai-suggestion-keep').addEventListener('click', () => {
          keep(text);
          row.remove();
          updateSuggestionPanelVisibility();
        });
        row.querySelector('.ai-suggestion-ignore').addEventListener('click', () => {
          row.remove();
          updateSuggestionPanelVisibility();
        });
        container.appendChild(row);
      }

      function keepTag(tagName) {
        // Workaround: tag input is replaced by tag autocomplete, so look it up when needed
        const tagsInput = document.getElementById('{{ form.tag_string.id_for_label }}');
        if (!tagsInput) {
          return;
        }
        const tags = tagsInput.value.trim();
        updateInput(tagsInput, tags ? `${tags} ${tagName}` : tagName);
      }

      function keepDescription(description) {
        updateInput(descriptionInput, description);
      }

      function requestSuggestions() {
        if (!urlInput.value) {
          return;
        }

        const query = new URLSearchParams({
          url: urlInput.value,
          title: titleInput.value,
          description: descriptionInput.value,
        });
        const requestUrl = `{% url 'linkding:api-root' %}bookmarks/suggest?${query}`;

        fetch(requestUrl)
          .then(response => (response.ok ? response.json() : null))
          .then(data => {
            if (!data) {
              return;
            }
            suggestionPanel.querySelectorAll('.ai-suggestion-row').forEach(row => row.remove());
            (data.suggested_tags || []).forEach(tagName => {
              addSuggestion(suggestedTagsContainer, tagName, keepTag);
            });
            if (data.description) {
              addSuggestion(suggestedDescriptionContainer, data.description, keepDescription);
            }
            updateSuggestionPanelVisibility();
          })
          .catch(() => {
            // the form stays usable; nothing is shown on a failed request
          });
      }

      suggestButton.addEventListener('click', requestSuggestions);
      {% endif %}
```

